class CamelCaseTransformationService:
    def convert_case(self, snake_identifier: str) -> str:
        tokens = snake_identifier.split("_")
        if not tokens:
            return ""
        head = tokens[0].lower()
        tail = "".join(t.capitalize() for t in tokens[1:] if t)
        return head + tail

