class EmailHandleMaskingPolicy:
    def obfuscate_email(self, address: str) -> str:
        if "@" not in address:
            return address
        user, domain = address.split("@", 1)
        if len(user) <= 2:
            masked_handle = user[0] + "***" if user else "***"
        else:
            masked_handle = user[0] + "***" + user[-1]
        return f"{masked_handle}@{domain}"

