class LCMComputationService:
    def calculate_lcm(self, first: int, second: int) -> int:
        if first == 0 or second == 0:
            return 0
        u, v = abs(first), abs(second)
        prod = u * v
        while v != 0:
            u, v = v, u % v
        return prod // u

