class FibonacciGeneratorService:
    def compute_term(self, index: int) -> int:
        if index < 0:
            raise ValueError("n must be non-negative")
        if index in (0, 1):
            return index
        prev, curr = 0, 1
        for _ in range(2, index + 1):
            prev, curr = curr, prev + curr
        return curr

