class SigmoidActivationEngine:
    LOWER_BOUND = -700.0
    UPPER_BOUND = 700.0

    def evaluate(self, scalar: float) -> float:
        if scalar < self.LOWER_BOUND:
            return 0.0
        if scalar > self.UPPER_BOUND:
            return 1.0
        return 1.0 / (1.0 + math.exp(-scalar))

