class ClusterAutoscalerReconciliationEngine:
    def reconcile(self, desired: int, actual: int) -> tuple[str, int]:
        discrepancy = desired - actual
        if discrepancy > 0:
            return ("SCALE_UP", discrepancy)
        elif discrepancy < 0:
            return ("SCALE_DOWN", abs(discrepancy))
        return ("STEADY", 0)

